     7	/**
     8	 * The shape every CSV report shares: a title line, the header, the rows and the total. Each report fills in only
     9	 * its name, its header and its content; a change to the shape of all reports is an edit to {@link #generate}.
    10	 *
    11	 * @param <P> what the report covers: a night, a month
    12	 */
    13	public abstract class Report<P> {
    14	
    15	    static final String INN_NAME = "Pousada Maré Alta";
    16	
    17	    protected static final Comparator<Reservation> BY_CHECK_IN_THEN_ID =
    18	            Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id);
    19	
    20	    /** The rows of a report, already formatted, and its last line. */
    21	    protected record Content(List<String> rows, String total) {}
    22	
    23	    public final String generate(P period) {
    24	        Content content = content(period);
    25	        StringBuilder csv = new StringBuilder();
    26	        csv.append(INN_NAME).append(',').append(name()).append(',').append(period).append('\n');
    27	        csv.append(header()).append('\n');
    28	        for (String row : content.rows()) {
    29	            csv.append(row).append('\n');
    30	        }
    31	        csv.append(content.total()).append('\n');
    32	        return csv.toString();
    33	    }
    34	
    35	    /** The name of the report, as it appears in the title line. */
    36	    protected abstract String name();
    37	
    38	    protected abstract String header();
    39	
    40	    protected abstract Content content(P period);
    41	}
