    46	import java.math.BigDecimal;
    47	import java.time.YearMonth;
    48	import java.util.ArrayList;
    49	import java.util.List;
    50	
    51	/**
    52	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
    53	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
    54	 */
    55	public final class RevenueReport extends Report<YearMonth> {
    56	
    57	    private final ReservationStore store;
    58	
    59	    public RevenueReport(ReservationStore store) {
    60	        this.store = store;
    61	    }
    62	
    63	    @Override
    64	    protected String name() {
    65	        return "revenue";
    66	    }
    67	
    68	    @Override
    69	    protected String header() {
    70	        return "reservation,room,check_in,check_out,status,amount";
    71	    }
    72	
    73	    @Override
    74	    protected Content content(YearMonth month) {
    75	        List<Reservation> withRevenue = new ArrayList<>();
    76	        for (Reservation reservation : store.all()) {
    77	            boolean keptMoney = reservation.amountKept().signum() > 0;
    78	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    79	            if (keptMoney && startsInMonth) {
    80	                withRevenue.add(reservation);
    81	            }
    82	        }
    83	        withRevenue.sort(BY_CHECK_IN_THEN_ID);
    84	
    85	        List<String> rows = new ArrayList<>();
    86	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
    87	        for (Reservation reservation : withRevenue) {
    88	            rows.add(reservation.id() + "," + reservation.roomNumber() + "," + reservation.checkIn() + ","
    89	                    + reservation.checkOut() + "," + reservation.status() + ","
    90	                    + reservation.amountKept().toPlainString());
    91	            revenue = revenue.add(reservation.amountKept());
    92	        }
    93	        return new Content(rows, "total," + revenue.toPlainString());
    94	    }
    95	}
